Sprite *create_pro_sprite(int x, int y,int sprite_case) {
    Sprite *sp = (Sprite *) malloc(sizeof(Sprite));
    if (sp == NULL) return NULL;
    xpm_image_t img;

    sp->map = xpm_load(profirst[0], XPM_8_8_8, &img);
    if (sp->map == NULL) {
        free(sp);
        return NULL;
    }
    
    sp->x = x;
    sp->y = y;
    sp->width = img.width;
    sp->height = img.height;
    sp->xspeed = 0;
    sp->yspeed = 0;
    sp->angle = 0;
    sp->rotation_speed = 0;
    sp->index=0;
    sp->cap=3;
    return sp;
}

void draw_pro_bar(Sprite *sp,uint8_t* buffer,int sprite_case) {
    switch(sprite_case) {
        case 0: sp->cap = 4; break;  
        case 1: sp->cap = 4; break;  
        case 2: sp->cap = 4; break;  
        case 3: sp->cap = 4; break; 
        case 4: sp->cap = 3; break;  
        default: return;
    }
    sp->index = (sp->index + 1) % sp->cap;
    xpm_image_t img;
    uint8_t *pixmap = NULL;
    switch(sprite_case) {
        case 0: pixmap = xpm_load(profirst[sp->index], XPM_8_8_8, &img); break;
        case 1: pixmap = xpm_load(prosecond[sp->index], XPM_8_8_8, &img); break;
        case 2: pixmap = xpm_load(prothird[sp->index], XPM_8_8_8, &img); break;
        case 3: pixmap = xpm_load(profourth[sp->index], XPM_8_8_8, &img); break;
        case 4: pixmap = xpm_load(profifth[sp->index], XPM_8_8_8, &img); break;
    }
    if (pixmap == NULL) return;
    
    for (int h = 0; h < img.height; h++) {
        for (int w = 0; w < img.width; w++) {
            int idx = (h*img.width+w)*3;
            uint8_t b = pixmap[idx];
            uint8_t g = pixmap[idx+1];
            uint8_t r = pixmap[idx+2];
            uint32_t color = direct_mode(r,g,b);
            if(r==0 && g==0 && b==0) {
                continue;
            }

            if (color != 0) {
                vg_draw_pixel_buffer(buffer, sp->x+w, sp->y+h , color);
            }
        }
    }
    free(pixmap);

}

void draw_pro_result(Sprite *sp,uint8_t* buffer,int sprite_case) {
    int index= sp->cap-1;
    xpm_image_t img;
    uint8_t *pixmap = NULL;
    switch(sprite_case) {
        case 0:
            pixmap = xpm_load(profirst[index], XPM_8_8_8, &img);
            break;
        case 1:
            pixmap = xpm_load(prosecond[index], XPM_8_8_8, &img);
            break;
        case 2:
            pixmap = xpm_load(prothird[index], XPM_8_8_8, &img);
            break;
        case 3:
            pixmap = xpm_load(profourth[index], XPM_8_8_8, &img);
            break;
        case 4:
            pixmap = xpm_load(profifth[index], XPM_8_8_8, &img);
            break;
        default: 
            return;

    }
    if (pixmap == NULL) return;
    
    for (int h = 0; h < img.height; h++) {
        for (int w = 0; w < img.width; w++) {
            int idx = (h*img.width+w)*3;
            uint8_t b = pixmap[idx];
            uint8_t g = pixmap[idx+1];
            uint8_t r = pixmap[idx+2];
            uint32_t color = direct_mode(r,g,b);
            if(r==0 && g==0 && b==0) {
                continue;
            }

            if (color != 0) {
                vg_draw_pixel_buffer(buffer, sp->x+w, sp->y+h , color);
            }
        }
    }
    free(pixmap);

}

void destroy_pro_bar(Sprite *sp) {
    if (sp == NULL) return;
    if (sp->map != NULL) {
        free(sp->map);
    }
    free(sp);
    sp=NULL;
}


